import { createHmac, randomBytes, timingSafeEqual } from "node:crypto";
import { SyncNode } from "@/models";
import type { ISyncNodeDocument } from "@/models";

/**
 * Center-side node credentials.
 *
 * A shop node calls the sync endpoints server-to-server, so it cannot present a
 * cashier's session cookie. It authenticates with a node id + secret instead:
 *
 *  - the secret is generated by the center and shown exactly once,
 *  - only an HMAC of it (peppered with JWT_SECRET) is stored,
 *  - comparison is constant-time,
 *  - a deactivated node is rejected even with the right secret.
 *
 * This is authentication only. Authorization still happens per row: every row
 * names the acting user, whose permissions are re-checked at the center.
 */

const NODE_ID_HEADER = "x-sync-node-id";
const NODE_KEY_HEADER = "x-sync-node-key";

export function hashNodeKey(key: string): string {
  const pepper = process.env.JWT_SECRET ?? "sync-node-key-pepper";
  return createHmac("sha256", pepper).update(key).digest("hex");
}

export function verifyNodeKey(key: string, expectedHash: string): boolean {
  const actual = Buffer.from(hashNodeKey(key), "hex");
  const expected = Buffer.from(expectedHash, "hex");
  if (actual.length !== expected.length) return false;
  return timingSafeEqual(actual, expected);
}

/** Generates a fresh node secret. The plaintext is returned only here. */
export function issueNodeKey(): { key: string; keyHash: string } {
  const key = randomBytes(32).toString("base64url");
  return { key, keyHash: hashNodeKey(key) };
}

export function readNodeCredentials(headers: Headers): { nodeId: string; key: string } | null {
  const nodeId = (headers.get(NODE_ID_HEADER) ?? "").trim();
  const key = (headers.get(NODE_KEY_HEADER) ?? "").trim();
  if (!nodeId || !key) return null;
  return { nodeId, key };
}

/** Resolves the calling node, or null when the credentials are not valid. */
export async function authenticateNode(headers: Headers): Promise<ISyncNodeDocument | null> {
  const credentials = readNodeCredentials(headers);
  if (!credentials) return null;

  const node = await SyncNode.findOne({ nodeId: credentials.nodeId });
  if (!node || node.status !== "active") return null;
  if (!verifyNodeKey(credentials.key, node.keyHash)) return null;

  return node;
}

/** Records node liveness (called by the sync endpoints, best-effort). */
export async function touchNode(
  nodeId: string,
  fields: { lastPushAt?: Date; lastPullAt?: Date; pushedRows?: number }
): Promise<void> {
  const update: Record<string, unknown> = { lastSeenAt: new Date() };
  if (fields.lastPushAt) update.lastPushAt = fields.lastPushAt;
  if (fields.lastPullAt) update.lastPullAt = fields.lastPullAt;
  await SyncNode.updateOne(
    { nodeId },
    {
      $set: update,
      ...(fields.pushedRows ? { $inc: { pushedRows: fields.pushedRows } } : {}),
    }
  );
}
